import {scenarioFor,defaultCalculation,normalizeField,estimateScenario} from './scenario-calculator.mjs';
import {selectedServices,placements} from './catalog.mjs';
const integer=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n);
const price=n=>integer(n)+' ₽';
const compact=n=>new Intl.NumberFormat('ru-RU',{notation:n>=1e7?'compact':'standard',maximumFractionDigits:1}).format(n);
export function createScenarioUI({state,pricing,task,icon,esc,onChange}){
 const $=s=>document.querySelector(s);
 const config=()=>scenarioFor(state.task,state);
 function calculation(){if(!state.calc||state.calc.taskId!==state.task)state.calc=defaultCalculation(state.task,{industry:state.industry,role:state.role});return state.calc;}
 const estimate=()=>estimateScenario(calculation(),pricing,state.placement);
 function control(f){
  const value=calculation().values[f.id];return `<div class="scenario-field"><label for="metric-${f.id}">${esc(f.label)}</label>${f.type==='select'?`<select id="metric-${f.id}" data-metric="${f.id}">${f.options.map(([v,label])=>`<option value="${v}" ${v===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`:`<input id="metric-${f.id}" data-metric="${f.id}" type="number" min="${f.min}" max="${f.max}" step="${f.id==='benchmarkMs'?'.01':'1'}" value="${value??''}" inputmode="${f.id==='benchmarkMs'?'decimal':'numeric'}" ${f.id==='benchmarkMs'?'placeholder="Если измеряли"':''}>`}${f.note?`<p class="field-note">${esc(f.note)}</p>`:''}</div>`;
 }
 function settings(){const c=calculation(),s=config(),llm=s.kind==='llm';return `<div class="settings-grid">${llm?`<label>Модель для оценки<select data-setting="modelId">${pricing.apiModels.map(m=>`<option value="${m.id}" ${m.id===c.modelId?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>`:''}${(!s.monthly||llm)&&!['training','custom'].includes(s.kind)?`<label>Дней работы в месяц<input type="number" data-setting="days" min="1" max="31" value="${c.days}"></label>`:''}${llm||['resources','vision'].includes(s.kind)?`<label>Часов активности в день<input type="number" data-setting="hours" min="1" max="24" value="${c.hours}"></label>`:''}${llm?`<label>Режим аренды GPU<select data-setting="gpuSchedule"><option value="always" ${c.gpuSchedule==='always'?'selected':''}>Весь месяц · 730 часов</option><option value="window" ${c.gpuSchedule==='window'?'selected':''}>Только в часы работы</option></select><span class="field-note">Для API не влияет на цену. Остановка GPU и время запуска требуют настройки.</span></label>`:''}${s.kind==='training'?`<label>Эпох обучения<input type="number" data-setting="epochs" min="1" max="20" value="${c.epochs}"></label><label>Время обучения, часов<input type="number" data-setting="trainingHours" min=".1" max="100000" step=".1" value="${c.trainingHours??''}" placeholder="Если измеряли"></label><label>GPU для обучения<select data-setting="trainingGpus">${[1,2,4,8].map(v=>`<option value="${v}" ${c.trainingGpus===v?'selected':''}>${v} H100</option>`).join('')}</select></label>`:''}<label class="check-label"><input type="checkbox" data-setting="sensitive" ${c.sensitive?'checked':''}>Есть особые требования к данным</label><label class="check-label"><input type="checkbox" data-setting="isolation" ${c.isolation?'checked':''}>Нужно выделенное оборудование</label></div><div id="launch-options"></div><button class="text-button" id="calc-method">Как посчитали ${icon('arrow')}</button>`;}
 function render(){const t=task(),s=config();calculation();$('#view').innerHTML=`<p class="eyebrow">Ваш сценарий</p><h1 tabindex="-1">${esc(t.name)}</h1><p class="scenario-description">${esc(t.result)}</p><div class="result-grid"><section class="parameters"><div class="section-heading"><h2>Оцените объём задачи</h2><span>Параметры можно менять</span></div><div class="metric-grid">${s.fields.map(control).join('')}</div>${s.kind==='custom'?'<p class="custom-help">Уточним ожидаемый результат, данные и объём работы вместе с архитектором.</p>':''}<div id="scenario-stats" class="scenario-stats"></div></section><section id="estimate-card" class="estimate-card" aria-live="polite" aria-atomic="true"></section></div><div class="placement-row"><label for="placement">Где должно работать решение?</label><select id="placement">${Object.entries(placements).map(([id,label])=>`<option value="${id}" ${state.placement===id?'selected':''}>${label}</option>`).join('')}</select></div><section class="solution-section"><h2>Сервисы для запуска</h2><div id="solution-products" class="solution-strip"></div></section><details class="scenario-details"><summary>Модель, способ запуска и допущения ${icon('down')}</summary>${settings()}</details><p class="pilot-next"><strong>Первый шаг:</strong> ${esc(t.next)}</p><div class="result-actions"><button class="back-button" data-step="2">${icon('back')} Другая задача</button><button class="primary" id="open-lead">Получить подборку после конференции ${icon('arrow')}</button></div>`;update();}
 function update(){
  const c=calculation(),s=config(),e=estimate(),w=e.workload,p=e.selected;
  $('#scenario-stats').innerHTML=w.stats.map(([n,label])=>`<div><strong>${compact(n)}</strong><span>${esc(label)}</span></div>`).join('');
  $('#solution-products').innerHTML=selectedServices(state.task,e.selectedId).map(x=>`<article><span class="solution-dot"></span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p></article>`).join('')||'<p>Состав решения определим после обсуждения вашей задачи.</p>';
  const excludes=`${task().products.includes('rag')?'База знаний, ':''}${task().products.includes('agents')?'работа агентов, ':''}${c.values.format==='scan'?'распознавание сканов, ':''}хранение, интеграции и внедрение — отдельно.`;
  if(e.status==='ready'){
   const scope=p.id==='api'?`Только вызовы ${e.model.name} по API`:p.id==='bm'?`${p.gpus} GPU H100 · серверы на полный месяц`:`${p.gpus} GPU H100 × ${integer(e.billableHours??(s.kind==='experiment'?c.values.volume:s.kind==='training'?c.trainingHours:c.hours*c.days))} часов`;
   const perUser=state.task==='code'?`≈ ${price(p.cost/Math.max(1,c.values.volume*c.values.activePercent/100))} на активного разработчика в месяц`:'';
   $('#estimate-card').innerHTML=`<p class="eyebrow">${p.id==='api'?'Бюджет модели':'Бюджет вычислений'}</p><p class="estimate-money">≈ ${price(p.cost)}</p><p class="estimate-period">${e.period}</p><p class="estimate-scope">${esc(scope)}</p>${perUser?`<p class="per-user">${perUser}</p>`:''}<p class="estimate-exclusions">${esc(excludes)}</p><p class="estimate-footnote">Предварительная оценка части решения. Тарифы ${esc(pricing.meta.updatedAt)}, ${pricing.meta.vatIncluded?'НДС включён':'НДС уточняется'}.</p>`;
  }else{
   const messages={benchmark:['Начнём с теста модели','Для цены нужен замер скорости на ваших изображениях.'],training:['Сначала замерим время обучения','Объём данных посчитан. Время GPU можно указать в деталях.'],placement:['Подберём решение под ваш контур','Параметры задачи сохранятся. Доступность сервисов и стоимость уточним с архитектором.'],blocked:['Уточним способ запуска',e.note],custom:['Обсудим и оценим задачу','В подборке сохраним ваше описание и вопросы для следующего шага.']};
   const [title,copy]=messages[e.status];$('#estimate-card').innerHTML=`<p class="eyebrow">Следующий шаг</p><h2 class="estimate-status">${esc(title)}</h2><p class="estimate-scope">${esc(copy)}</p><p class="estimate-footnote">Можно оставить контакты и получить подборку после конференции.</p>`;
  }
  const launch=$('#launch-options');if(launch)launch.innerHTML=`<div class="launch-heading"><h3>Способ запуска</h3><p>Режим выбираете вы. Рост нагрузки не переключает его автоматически.</p></div>${e.options.map(o=>`<div class="launch-option ${o.id===e.selectedId?'selected':''}"><div><strong>${esc(o.title)}</strong><span>${o.ok?esc(o.product):esc(o.reason)}</span></div><span>${o.ok?'≈ '+price(o.cost):'Уточнить'}</span><button type="button" data-launch="${o.id}" ${!o.ok||o.id===e.selectedId?'disabled':''}>${o.id===e.selectedId?'Выбрано':'Выбрать'}</button></div>`).join('')}<p class="field-note">${esc(e.note||'Платите за входные и выходные токены. Скорость и качество модели проверяются отдельно.')}</p>`;
 }
 function changed(){update();onChange?.();}
 function input(event){const t=event.target,c=calculation(),f=config().fields.find(f=>f.id===t.dataset.metric);if(f&&f.type==='number'){if(t.value==='')return true;c.values[f.id]=normalizeField(f,t.value);changed();return true;}if(t.dataset.setting&&t.type==='number'){setSetting(t);return true;}return false;}
 function setSetting(t){const c=calculation(),key=t.dataset.setting;if(t.type==='checkbox')c[key]=t.checked;else if(t.type==='number'){if(t.value===''){if(key==='trainingHours')c[key]=null;else return;}else c[key]=Math.max(Number(t.min),Math.min(Number(t.max),Number(t.value)));}else c[key]=key==='trainingGpus'?Number(t.value):t.value;changed();}
 function change(event){const t=event.target;if(t.id==='placement'){state.placement=t.value;changed();return true;}if(t.dataset.setting){setSetting(t);return true;}const f=config().fields.find(f=>f.id===t.dataset.metric);if(f){const c=calculation();c.values[f.id]=normalizeField(f,t.value);if(f.id==='mode'){c.values.frequency=t.value==='completion'?200:20;render();onChange?.();}else{t.value=c.values[f.id]??'';changed();}return true;}return false;}
 function click(event){const button=event.target.closest('[data-launch]');if(button&&!button.disabled){calculation().launch=button.dataset.launch;changed();return true;}return false;}
 function showMethod(){const e=estimate(),w=e.workload;$('#method-content').innerHTML=`<div class="dialog-header"><h2 id="method-title">Как посчитали</h2><button class="dialog-close" data-close aria-label="Закрыть">${icon('close')}</button></div><p>${esc(w.formula||e.note)}</p><ul class="method-list">${w.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>${w.tokIn?`<p>${integer(w.tokIn)} входных и ${integer(w.tokOut)} выходных токенов в месяц.</p><p>API: входные токены × ${e.model.inPrice} ₽ / млн + выходные × ${e.model.outPrice} ₽ / млн.</p>`:''}<p>${esc(e.note)}</p><p>Проверка качества, интеграции, хранение и эксплуатация решения оцениваются отдельно. Цифры не заменяют нагрузочный тест и коммерческое предложение.</p><p class="field-note">Тарифы ${esc(pricing.meta.updatedAt)}. Версия методики 2026-10-23.2.</p>`;$('#method-dialog').showModal();}
 return {render,update,calculation,estimate,click,input,change,showMethod};
}
